<?php

namespace Controllers\History;

use Controllers\Utils\Sanitize;

/**
 *  HTML rendering of the history lines
 */
class Display
{
    // Maximum length of a value to be displayed as a label, longer values are displayed as text
    private const LABEL_MAX_LENGTH = 60;

    /**
     *  Return the action of a history line, as HTML
     *  Before 5.1.0, actions were fully escaped before being stored: they don't contain any raw tag and must be decoded
     *  The action is then sanitized to only keep the HTML tags generated by the application, as it may contain untrusted data
     */
    public static function action(string $action): string
    {
        if (!str_contains($action, '<')) {
            $action = htmlspecialchars_decode($action);
        }

        return Sanitize::html($action);
    }

    /**
     *  Return the decoded details of a history line: ['changes' => [...], 'params' => [...]]
     */
    public static function details(string|null $details): array
    {
        if (empty($details)) {
            return ['changes' => [], 'params' => []];
        }

        $decoded = json_decode($details, true);

        if (!is_array($decoded)) {
            return ['changes' => [], 'params' => []];
        }

        return [
            'changes' => is_array($decoded['changes'] ?? null) ? $decoded['changes'] : [],
            'params'  => is_array($decoded['params'] ?? null) ? $decoded['params'] : []
        ];
    }

    /**
     *  Return a value as HTML: lists and short values are displayed as labels, other values as text
     *  $label is the label class to use (label-white, label-red, label-green)
     */
    public static function value(string|array $value, string $label = 'label-white'): string
    {
        if (is_array($value)) {
            if (empty($value)) {
                return '<p class="mediumopacity-cst">None</p>';
            }

            $html = '<div class="flex flex-wrap column-gap-5 row-gap-5">';

            foreach ($value as $item) {
                $html .= '<span class="' . $label . '">' . htmlspecialchars((string) $item) . '</span>';
            }

            return $html . '</div>';
        }

        if ($value === '') {
            return '<p class="mediumopacity-cst">Empty</p>';
        }

        if ($value === 'true' or $value === 'false') {
            $value = $value === 'true' ? 'Yes' : 'No';
        }

        // Short values of a change are displayed as labels, to highlight the before and after values
        if ($label != 'label-white' and mb_strlen($value) <= self::LABEL_MAX_LENGTH and !str_contains($value, "\n")) {
            return '<div><span class="' . $label . '">' . htmlspecialchars($value) . '</span></div>';
        }

        return '<p class="wordbreakall">' . nl2br(htmlspecialchars($value)) . '</p>';
    }

    /**
     *  Return a change as HTML cells: field, before and after
     *  For lists, the removed values are displayed in the 'before' cell and the added values in the 'after' cell
     */
    public static function change(array $change): string
    {
        $html = '<div><p>' . htmlspecialchars((string) ($change['field'] ?? '')) . '</p>';

        // Secret values are never stored
        if (!empty($change['secret'])) {
            return $html . '</div><p class="mediumopacity-cst">Hidden</p><p class="mediumopacity-cst">Changed (hidden)</p>';
        }

        $before = $change['before'] ?? '';
        $after  = $change['after'] ?? '';

        if (!is_array($before) or !is_array($after)) {
            return $html . '</div>' . self::value($before, 'label-red') . self::value($after, 'label-green');
        }

        $removed = array_values(array_diff($before, $after));
        $added   = array_values(array_diff($after, $before));
        $kept    = count($after) - count($added);

        if ($kept > 0) {
            $html .= '<p class="note">' . $kept . ' unchanged</p>';
        }

        $html .= '</div>';
        $html .= !empty($removed) ? self::value($removed, 'label-red') : '<p class="mediumopacity-cst">—</p>';
        $html .= !empty($added) ? self::value($added, 'label-green') : '<p class="mediumopacity-cst">—</p>';

        return $html;
    }
}
